  },
  {
    "role": "user",
    "content": "Nothing, I'm just playing with you."
  },
  {
    "role": "assistant",
    "content": "Oh ok, in that case should you need anything just let me know!"
  },
  {
    "role": "user",
    "content": "Actually, I have something I want to tell you"
  }
]

